1	// baselining worker — the DETERMINISTIC self-refresh, as prework
2	// (task-prework DESIGN §7, E4). This is `agent_model: 'sonnet'` with
3	// `prework: 'node worker.mjs'`, so the scheduler runs THIS FILE as a
4	// subprocess (cwd = this task dir) bounded by `prework_timeout`,
5	// BEFORE any agent. It absorbs everything about the nightly refresh that is
6	// dependency-free code — so most nights are AGENTLESS and quiet, and an agent is
7	// requested only when real judgment is left (owner decision, 2026-07-23):
8	//
9	//   agent requested  ⇔  a pending AGENTIC migration note exists
10	//                    OR  the converge changed things AND check_the_world is not green.
11	//   no change, or changed-but-green with no agentic note  →  agentless night.
12	//
13	// What it does, Action-side, over the one sanctioned non-MCP surface (the Action
14	// GITHUB_TOKEN in env) and a direct PUBLIC canon fetch (owner §10: canon is
15	// public — no token, no tarball channel):
16	//   1. shallow-clone canon at its head sha (then drop .git → a rootless tree, so
17	//      apply-vendor-set skips the ancestry guards that a shallow clone can't
18	//      satisfy — it is head by construction);
19	//   2. run the CLONED canon's vendoring/apply-vendor-set.mjs to converge
20	//      .claudinite/shared/ and stamp it (compute+apply, one snapshot);
21	//   3. run the cloned converge-wiring.mjs (scheduler workflow + hashed cron + the
22	//      tasks' declared required_secrets, settings hooks, retired-import removal),
23	//      and ask the owner for any declared secret the repo hasn't configured;
24	//   4. apply the MECHANICAL migration notes (aliases/materialize/rewrite) via the
25	//      cloned migrations/apply.mjs — idempotent;
26	//   5. detect pending AGENTIC notes (registry.mjs `agenticMigrations`, gated on
27	//      the prior stamp day, same-day inclusive #330) and, if any, HOLD the stamp
28	//      at the day before the earliest one so the agent still sees the note (the
29	//      stamp/agentic coupling rule);
30	//   6. deliver the converge as ONE commit on the per-cycle maintenance branch via
31	//      NATIVE git (dispose of the family's open PR — merge it if its own runs
32	//      verified it, else close it — then cut a fresh dated branch and open the
33	//      PR), arming auto-merge per the
34	//      member's `maintenance.delivery` and DISPATCHING the repo's PR CI on the
35	//      branch — the GITHUB_TOKEN push emits no pull_request run of its own
36	//      (#565), so the checks the arm waits on must be started explicitly;
37	//   7. request the agent (write CLAUDINITE_REQUEST_AGENT) only when judgment is
38	//      left — the scheduler files `ready-for-agent` iff this file appears (§3,
39	//      conditional handoff). NO code→agent data channel: the file is a pure
40	//      control signal; the agent discovers its work by reading the repo (the
41	//      pushed branch, the held stamp, the pending note).
42	//
43	// Self-contained — imports only node builtins statically (the pack-independence
44	// barrier forbids reaching into the engine). The vendoring/migrations machinery
45	// is canon-internal (vendoring/ is never vendored, #385), so the worker INVOKES
46	// the freshly-fetched canon's scripts as subprocesses and DYNAMIC-imports its
47	// registry from the temp clone path — never a static import of engine code.
48	//
49	// This SUPERSEDES the per-cycle maintenance-branch naming of PR #407 (that PR
50	// reworked the OLD fleet-apply MCP path; baselining's delivery is native git
51	// Action-side and carries its own prefix/find-by-prefix here).
52	
53	import { execFileSync } from 'node:child_process';
54	import { readFileSync, writeFileSync, existsSync, rmSync, mkdtempSync } from 'node:fs';
55	import { join } from 'node:path';
56	import { tmpdir } from 'node:os';
57	import { pathToFileURL } from 'node:url';
58	
59	const CANON_URL = 'https://github.com/missingbulb/Claudinite.git'; // public — no token
60	const MAINT_PREFIX = 'claudinite/maintenance';
61	const API = 'https://api.github.com';
62	
63	// --- pure helpers (exported, unit-tested git-free) --------------------------
64	
65	// The member's delivery preference, normalized. `push`/`auto` → auto-merge and
66	// `pr` → review are the permanent legacy aliases (same tolerance as fleet-apply);
67	// anything else is invalid (null) and fails the run rather than guessing.
68	export function normalizeDelivery(raw) {
69	  const v = String(raw ?? '').trim();
70	  if (v === 'auto-merge' || v === 'auto' || v === 'push') return 'auto-merge';
71	  if (v === 'review' || v === 'pr') return 'review';
72	  return null;
73	}
74	
75	// The default a repo gets when it never declared one.
76	export const DEFAULT_DELIVERY = 'auto-merge';
77	
78	// `maintenance.delivery` is always EXPLICIT — but a key that is simply absent is
79	// DRIFT, not an error, and drift is what a converge exists to repair. A repo
80	// adopted before the key existed, or one whose key was hand-removed, would
81	// otherwise fail baselining every night forever with nothing that could ever fix
82	// it (the only writer is check_the_world --init, which runs once at adoption).
83	// So: materialize the default into .claudinite-checks.json and carry on — it
84	// rides the same maintenance commit as the rest of the converge, and the repo
85	// self-heals on one cycle.
86	//
87	// An UNRECOGNIZED value is a different thing entirely: someone wrote an intent
88	// the worker cannot honour, and silently substituting a default would deliver
89	// the opposite of what they asked for. That still fails the run (delivery: null).
90	//
91	// Returns { delivery, materialize } — `delivery` null only for the unrecognized
92	// case. A content-free value (empty/whitespace) carries no intent, so it is
93	// treated as absent rather than as a typo.
94	export function resolveDelivery(raw) {
95	  if (raw == null || String(raw).trim() === '') {
96	    return { delivery: DEFAULT_DELIVERY, materialize: true };
97	  }
98	  return { delivery: normalizeDelivery(raw), materialize: false };
99	}
100	
101	// The pending AGENTIC notes: those dated on/after the DAY of the prior stamp
102	// (same-day inclusive, #330), oldest first. `agenticList` is registry.mjs
103	// `agenticMigrations(all)` — already filtered to records carrying a valid
104	// `agentic` note (a malformed note throws THERE, aborting the run loudly).
105	export function pendingAgentic(agenticList, priorUpdated) {
106	  const priorDay = String(priorUpdated ?? '').slice(0, 10);
107	  return [...(agenticList ?? [])]
108	    .filter((m) => !priorDay || String(m.landed) >= priorDay)
109	    .sort((a, b) => String(a.landed).localeCompare(String(b.landed)));
110	}
111	
112	// HOLD the stamp at the day before the earliest pending agentic note (the
113	// stamp/agentic coupling rule): the note stays selected next run until the agent
114	// lands it and advances the stamp itself. Returns the held ISO datetime, or null
115	// when nothing is pending (the stamp advances normally).
116	export function heldStamp(pending) {
117	  if (!pending?.length) return null;
118	  const d = new Date(`${String(pending[0].landed).slice(0, 10)}T00:00:00.000Z`);
119	  d.setUTCDate(d.getUTCDate() - 1);
120	  return d.toISOString();
121	}
122	
123	// A per-cycle maintenance branch name — dated + a short seed so each cycle gets a
124	// distinct branch (superseding #407's scheme, native-git side). `seed` is passed
125	// in so this is pure; main() generates it.
126	export function maintenanceBranchName(dateStr, seed) {
127	  return `${MAINT_PREFIX}-${dateStr}-${seed}`;
128	}
129	
130	// The family's open maintenance PR, found by head-branch PREFIX (the name carries
131	// a per-cycle seed, so the prefix is what identifies the family): the cycle
132	// DISPOSES of this one — merge or close — before cutting its own, which is what
133	// keeps them from piling up night-over-night. null → nothing to dispose of. The
134	// whole PR is returned, not just its ref, because disposal needs its number and
135	// head sha.
136	export function openMaintenancePull(pulls, prefix = MAINT_PREFIX) {
137	  return (pulls ?? []).find((pr) => String(pr?.head?.ref ?? '').startsWith(prefix)) ?? null;
138	}
139	
140	// Its head branch alone — the shape most callers want.
141	export function openMaintenanceBranch(pulls, prefix = MAINT_PREFIX) {
142	  return openMaintenancePull(pulls, prefix)?.head?.ref ?? null;
143	}
144	
145	// The paths this stage is STRUCTURALLY UNABLE to deliver. deliver() pushes with the
146	// Action's GITHUB_TOKEN, and GitHub refuses to let that token create or update anything
147	// under `.github/workflows/` — there is no `permissions:` key that grants it. The refusal
148	// is remote-side and rejects the WHOLE ref, so a workflow file left in the commit fails
149	// the entire push, taking the mount convergence, the wiring and every other note with it.
150	//
151	// So the converge withholds exactly these paths and hands them to the AGENT stage, whose
152	// writes go through the session's MCP GitHub tools — a credential that does hold the
153	// `workflows` permission. The agent re-runs the same mechanical apply in its own checkout
154	// to produce them.
155	//
156	// It covers `convergeWiring`'s scheduler workflow as much as any pack-owned one.
157	export const UNPUSHABLE_PREFIX = '.github/workflows/';
158	export function withheldWorkflowPaths(changedPaths) {
159	  return (changedPaths ?? []).filter((p) => p.startsWith(UNPUSHABLE_PREFIX));
160	}
161	
162	// The escalation decision (owner, 2026-07-23): agent iff a pending agentic note,
163	// or a real change the deterministic converge left non-green. No change, or a
164	// green change with no agentic note, stays agentless.
165	//
166	// It returns the REASON, not a bit — `null` for an agentless night, otherwise
167	// `{ code, detail }`. The worker knew which of four conditions fired and then threw
168	// it away; the agent it woke re-derived all four from scratch, and on
169	// EdFringeAllocator#82 re-derived them WRONG (it reported "preprocessing created
170	// nothing" about a cycle that had merged its PR a second earlier) and closed a
171	// six-minute run as a no-op. `code` is the stable identifier a consumer branches on;
172	// `detail` is the sentence a human reads in the dispatch issue.
173	//
174	// It names the CONDITION and its counts, never the findings themselves — those stay
175	// in the repo for the agent to re-run (DESIGN §3, the no-code→agent-data-channel rule;
176	// the named exception is identity, not content).
177	//
178	// The branch ORDER is the escalation precedence, most-specific first: a night with a
179	// pending note and a red check is a note night, because the note is what the agent
180	// must apply and the red check may well be the note's own doing.
181	export function escalation({
182	  pendingCount, meaningfulChange, checksPass, selftestOk = true, withheldCount = 0,
183	  checksCrashed = false, selftestCrashed = false,
184	}) {
185	  if (pendingCount > 0) {
186	    return { code: 'agentic-notes', detail: `${pendingCount} pending agentic migration note(s) to apply` };
187	  }
188	  // A withheld workflow file is work this stage COULD not do, not work it chose to
189	  // leave: without the agent, the file simply never lands, and the converge would
190	  // report itself clean while the repo stays un-updated.
191	  if (withheldCount > 0) {
192	    return {
193	      code: 'withheld-workflows',
194	      detail: `${withheldCount} workflow file(s) the Action token cannot push — only the agent's credential can land them`,
195	    };
196	  }
197	  // A converged mount that cannot pass its own self-test is the judgment case
198	  // whether or not the converge "changed" anything a diff can see: broken
199	  // machinery reports no findings precisely because it is not running.
200	  if (!selftestOk) {
201	    return selftestCrashed
202	      ? { code: 'selftest-could-not-run', detail: 'the converged mount\'s self-test could not run at all — machinery, not content' }
203	      : { code: 'selftest-failed', detail: 'the converged mount FAILED its self-test — the machinery that runs the rules is not intact' };
204	  }
205	  if (Boolean(meaningfulChange) && !checksPass) {
206	    return checksCrashed
207	      ? { code: 'checks-could-not-run', detail: 'check_the_world could not run on the converged tree — no verdict was produced' }
208	      : { code: 'checks-not-green', detail: 'check_the_world reported findings on the converged tree that the deterministic pass could not fix' };
209	  }
210	  return null;
211	}
212	
213	// The same decision as a bit, for the callers that only need the verdict. Derived
214	// rather than reimplemented — two copies of a four-branch precedence is exactly the
215	// drift the corpus forbids.
216	export function shouldRequestAgent(signals) {
217	  return escalation(signals) !== null;
218	}
219	
220	// The scheduler hands the worker a path to signal the agent through; writing it
221	// requests the agent stage (run.mjs files `ready-for-agent` iff it appears).
222	export const AGENT_REQUEST_MARKER = 'agent-requested';
223	
224	// --- CI dispatch on the maintenance PR (#565) --------------------------------
225	// The branch push and the PR open in deliver() both ride the Action's
226	// GITHUB_TOKEN, and GitHub suppresses workflow runs for events that token
227	// authors (its recursion guard) — so the maintenance PR gets NO pull_request
228	// run, auto-merge arms against a green that never arrives, and the PR sits open
229	// forever (#565; the canon-only variant was #432). The guard's one documented
230	// exception is workflow_dispatch: a dispatch POSTed with GITHUB_TOKEN does start
231	// a run, the run's check runs land on the branch-head sha, and that sha is what
232	// the PR's merge gate reads. So deliver() starts the PR's checks itself:
233	// dispatch every workflow that WOULD have run on pull_request and CAN be
234	// dispatched.
235	//
236	// "Suppresses" is only half true, and the other half is #455/#205/#95: on some
237	// members GitHub CREATES the pull_request run and parks it at `action_required`
238	// awaiting an approval nobody clicks. The dispatch above still supplies the real
239	// green, but the parked run is what auto-merge refuses over — which is why
240	// arming is not the end of the story and pullDisposition exists.
241	//
242	// Reading the triggers is a best-effort TEXTUAL scan of a workflow's top-level
243	// `on:` block (the worker is dependency-free — no YAML parser). It covers the
244	// shapes workflows actually use: a block map of trigger keys (with or without
245	// nested config), the inline scalar, and the inline list.
246	export function workflowTriggers(yaml) {
247	  const lines = String(yaml ?? '').split('\n');
248	  const onAt = lines.findIndex((l) => /^(['"]?)on\1\s*:/.test(l));
249	  if (onAt === -1) return [];
250	  const inline = lines[onAt].replace(/^(['"]?)on\1\s*:/, '').replace(/#.*$/, '').trim();
251	  if (inline) return inline.replace(/[[\]]/g, '').split(',').map((s) => s.trim()).filter(Boolean);
252	  const triggers = [];
253	  let childIndent = null;
254	  for (let i = onAt + 1; i < lines.length; i += 1) {
255	    const line = lines[i];
256	    if (!line.trim() || line.trim().startsWith('#')) continue;
257	    const indent = line.length - line.trimStart().length;
258	    if (indent === 0) break;                        // next top-level key — on: is done
259	    childIndent = childIndent ?? indent;            // first child fixes the trigger level
260	    if (indent !== childIndent) continue;           // nested config under a trigger
261	    const m = /^([A-Za-z_]+)\s*:/.exec(line.trim());
262	    if (m) triggers.push(m[1]);
263	  }
264	  return triggers;
265	}
266	
267	// The dispatch plan over the repo's workflow files ({name, content} each):
268	// `dispatch` — runs on pull_request AND carries workflow_dispatch (start these);
269	// `missing`  — runs on pull_request but CANNOT be dispatched (name these in the
270	// log: adding `workflow_dispatch:` to that file's `on:` is the owner's one-line
271	// fix, and silence here would read as "no CI expected" when CI was expected).
272	// A workflow with no pull_request trigger is never touched — dispatchable-but-
273	// unrelated workflows (a release orchestrator, say) must not fire nightly.
274	export function ciDispatchPlan(files) {
275	  const dispatch = [];
276	  const missing = [];
277	  for (const { name, content } of files ?? []) {
278	    const triggers = workflowTriggers(content);
279	    if (!triggers.includes('pull_request')) continue;
280	    (triggers.includes('workflow_dispatch') ? dispatch : missing).push(name);
281	  }
282	  return { dispatch, missing };
283	}
284	
285	// --- I/O shell (validated by the live pilot, not unit tests) ----------------
286	
287	const git = (args, opts = {}) =>
288	  execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });
289	// `opts` exists for ONE reason: `cwd`. This worker's own cwd is the task dir INSIDE the
290	// mount (prework.mjs spawns it there), and step 2 deletes that whole tree before
291	// re-copying it — so from the vendor step onward this process is running in an unlinked
292	// directory, and every child it spawns inherits it. A child that calls `process.cwd()`
293	// dies with `ENOENT … uv_cwd` (#689). Children are therefore pointed at the repo root,
294	// which is the directory they were always meant to be working in.
295	const node = (args, extraEnv = {}, opts = {}) =>
296	  execFileSync(process.execPath, args, {
297	    encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], env: { ...process.env, ...extraEnv }, ...opts,
298	  });
299	
300	async function gh(token, path, { method = 'GET', body } = {}) {
301	  const res = await fetch(`${API}${path}`, {
302	    method,
303	    headers: {
304	      authorization: `Bearer ${token}`,
305	      accept: 'application/vnd.github+json',
306	      'x-github-api-version': '2022-11-28',
307	      ...(body ? { 'content-type': 'application/json' } : {}),
308	    },
309	    body: body ? JSON.stringify(body) : undefined,
310	  });
311	  let json = null;
312	  try { json = await res.json(); } catch { /* empty body */ }
313	  return { status: res.status, json };
314	}
315	
316	// The outcome of running one gate script, from what `node()` threw (or didn't).
317	// PURE, so the four shapes are testable without a repo on disk.
318	//
319	// `catch { return false }` was the whole of this before, and it collapsed four
320	// different events into one indistinguishable bit: findings, a crash, a signal kill,
321	// and a script that isn't there. `node()` already pipes stdout/stderr, so the
322	// findings were in the thrown error's `.stdout` all along and the bare catch dropped
323	// them — leaving the escalation they caused unexplainable after the fact
324	// (EdFringeAllocator#82: a run that escalated on a check which passes everywhere it
325	// can be re-run, with no record of what it saw).
326	//
327	// `crashed` is the distinction that matters most: a non-zero EXIT is a verdict about
328	// the repo's content, while a null status — signal kill, spawn failure — means no
329	// verdict was produced at all. Both still escalate to the agent (a gate that cannot
330	// answer is not permission to proceed), but they are no longer the same sentence.
331	export function gateOutcome(error) {
332	  if (!error) return { ok: true, ran: true, crashed: false, status: 0, output: '' };
333	  const status = Number.isInteger(error.status) ? error.status : null;
334	  const output = `${error.stdout ?? ''}${error.stderr ?? ''}`.trim();
335	  return { ok: false, ran: true, crashed: status === null, status, output };
336	}
337	
338	// A gate that isn't vendored at all is nothing to run — not a failure. Distinct from
339	// `crashed`, which is a gate that exists and could not answer.
340	export const GATE_ABSENT = Object.freeze({ ok: true, ran: false, crashed: false, status: null, output: '' });
341	
342	// Run check_the_world against the converged repo. Green means it exited clean (no
343	// blocking findings); anything else is judgment left, with the reason attached.
344	function runCheckTheWorld(root) {
345	  const cw = join(root, '.claudinite/shared/engine/checks/check_the_world.mjs');
346	  if (!existsSync(cw)) return GATE_ABSENT; // no vendored checks to gate on
347	  try { node([cw], { CLAUDE_PROJECT_DIR: root }, { cwd: root }); return gateOutcome(null); }
348	  catch (e) { return gateOutcome(e); }
349	}
350	
351	// REHEARSAL MODE (per-project-scheduling rehearsal, #593 phase 0). A run may be
352	// pointed at a canon BRANCH instead of its default head, so a canon change can be
353	// tried against a real repo before it merges. `CLAUDINITE_CANON_REF` selects the
354	// ref; `CLAUDINITE_CANON_URL` a fork.
355	//
356	// The stamp is the whole reason this needs its own decision rather than an extra
357	// clone argument. A branch head is NOT on trunk, and stamping it is precisely the
358	// shape vendoring's #328 anti-rewind guard refuses to write over afterwards
359	// (`ref-not-on-trunk`, which the sheepdog freshness sweep reads as WEDGED, not
360	// late) — a rehearsal would leave the repo unable to baseline ever again. This
361	// was not hypothetical: it happened by hand on 2026-07-30, to all thirteen
362	// members at once, from a converge run out of an unmerged branch.
363	//
