424	// What the base branch requires before a merge, from the two reads the Action's
425	// GITHUB_TOKEN can make: the branch's `protected` flag and the ruleset rules
426	// that apply to it (deliberately NOT /branches/{base}/protection, which wants
427	// admin). Rule types that queue a PR gate it; rules about pushes and deletions
428	// do not. An unreadable answer is UNKNOWN, never absent — unknown assumes a
429	// gate, so the caller arms rather than merging past a gate it cannot see.
430	const GATING_RULE_TYPES = ['pull_request', 'required_status_checks', 'merge_queue', 'required_deployments'];
431	export function classifyMergeGate({ branchStatus, branchJson, rulesStatus, rulesJson }) {
432	  if (branchStatus !== 200 || typeof branchJson?.protected !== 'boolean') return 'unknown';
433	  if (branchJson.protected) return 'present';
434	  if (rulesStatus !== 200 || !Array.isArray(rulesJson)) return 'unknown';
435	  return rulesJson.some((r) => GATING_RULE_TYPES.includes(r?.type)) ? 'present' : 'absent';
436	}
