438	async function readMergeGate(token, repo, base) {
439	  const branch = await gh(token, `/repos/${repo}/branches/${encodeURIComponent(base)}`);
440	  const rules = await gh(token, `/repos/${repo}/rules/branches/${encodeURIComponent(base)}`);
441	  return classifyMergeGate({
442	    branchStatus: branch.status, branchJson: branch.json,
443	    rulesStatus: rules.status, rulesJson: rules.json,
444	  });
445	}
