558	function runSelfTest(root) {
559	  const st = join(root, '.claudinite/shared/engine/selftest.mjs');
560	  if (!existsSync(st)) return GATE_ABSENT;
561	  try { node([st, '--strict'], { CLAUDE_PROJECT_DIR: root }, { cwd: root }); return gateOutcome(null); }
562	  catch (e) { return gateOutcome(e); }
563	}
564	
565	// What a gate said, for the LOG — the full text, not a summary. This is the one
566	// place the findings belong: the Action log is an observability surface nothing
567	// reads programmatically, so it carries everything, while the dispatch issue
568	// carries only the condition (preprocess.mjs, the §3 exception).
569	function logGateOutput(label, outcome) {
570	  const body = outcome.output ? `\n${outcome.output}` : ' (no output)';
571	  console.log(`baselining: ${label} ${outcome.crashed ? 'COULD NOT RUN' : `exited ${outcome.status}`} —${body}`);
572	}
