586	  const openPr = openMaintenancePull(Array.isArray(pulls) ? pulls : []);
587	  let pr = null;
588	  let merged = false;
589	
590	  if (openPr?.number) {
591	    // `wait` is the one case that keeps the PR: its checks are still running and
592	    // may yet land it. Skip this cycle entirely rather than race them — the
593	    // converge is idempotent, so tomorrow simply does it again.
594	    const kept = await disposeOpenPull(token, repo, openPr, delivery)
595	      .catch((e) => { console.log(`baselining: disposing of PR #${openPr.number} failed: ${e.message}`); return openPr; });
596	    if (kept) {
597	      console.log(`baselining: PR #${openPr.number} still stands — leaving this cycle's converge undelivered`);
598	      // Same shape as the delivery path below — the caller reads `.branch`/`.pr`
599	      // unconditionally, and the bare-ref return this used to make crashed it.
600	      return { branch: kept.head?.ref ?? null, pr: kept.number ?? openPr.number, merged: false };
601	    }
602	  }
603	
604	  const branch = maintenanceBranchName(new Date().toISOString().slice(0, 10), seed);
605	
606	  git(['-C', root, 'checkout', '-B', branch]);
607	  git(['-C', root, 'add', '-A']);
608	  // Withhold what this token cannot push (see withheldWorkflowPaths). Unstaged, not
609	  // reverted: the file stays in the working tree so nothing here has to reason about
610	  // restoring it, and the runner is discarded at job end either way. The agent lands
611	  // them on this same branch afterwards.
612	  for (const p of withheld) git(['-C', root, 'restore', '--staged', p]);
613	  // With everything else staged, a converge whose ONLY content was a workflow file has
614	  // nothing left to commit. It still needs the branch and the PR — that is where the
615	  // agent does its half — so the commit is allowed to be empty rather than skipped.
616	  const staged = git(['-C', root, 'diff', '--cached', '--name-only']).split('\n').filter(Boolean);
617	  const note = withheld.length
618	    ? `\n\nWithheld for the agent stage (the Action token cannot push a workflow file):\n${withheld.map((p) => `- ${p}`).join('\n')}`
619	    : '';
