624	  git(['-C', root, 'push', '--force', remote, `HEAD:refs/heads/${branch}`]);
625	
626	  const body = delivery === 'auto-merge'
627	    ? 'Automated Claudinite maintenance (deterministic converge + any migration notes). Re-cut each cycle; auto-merges once this repo\'s checks pass.'
