658	  // landing poll waits to see registered before it judges anything (landAttempt).
659	  const expected = ci?.dispatch.length ?? 0;
660	
661	  if (pr?.number) {
662	    const gate = pr ? await readMergeGate(token, repo, base).catch(() => 'unknown') : 'unknown';
