691	      // waiting on it here would add a poll to every healthy repo for nothing.
692	      if (!armed && await landNow(token, repo, pr, delivery, expected)) merged = true;
693	    }
694	  }
695	  // What this cycle delivered. The scheduler records it in the dispatch issue, which is
696	  // the agent's source for these artifacts.
697	  return { branch, pr: pr?.number ?? null, merged };
698	}
699	
700	// The I/O half of same-cycle landing: poll this PR's head sha until its runs have
701	// concluded, then merge on the same evidence disposal would use a day later.
702	// Returns true iff it merged. Best-effort throughout — every failure path leaves
703	// the PR exactly as the arm left it, which is what the next cycle expects.
704	const sleep = (ms) => new Promise((resolve) => { setTimeout(resolve, ms); });
