706	async function landNow(token, repo, pr, delivery, expected = 0) {
707	  const started = Date.now();
708	  for (;;) {
709	    const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha ?? ''}&per_page=100`);
710	    if (status !== 200) {
711	      console.log(`baselining: could not read this cycle's runs for PR #${pr.number} (HTTP ${status}) — leaving it for the next cycle`);
712	      return false;
713	    }
714	    const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
715	    const attempt = landAttempt({ delivery, runs, expected, elapsedMs: Date.now() - started });
716	
717	    if (attempt === 'poll') { await sleep(LAND_POLL_MS); continue; }
718	    if (attempt === 'give-up') {
719	      console.log(`baselining: PR #${pr.number} not landable this cycle (${failureSummary(runs)})`
720	        + ' — leaving it open for the next cycle to dispose of');
721	      return false;
722	    }
723	
724	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
725	      method: 'PUT', body: { merge_method: 'squash' },
726	    });
727	    if (res.status === 200) {
728	      console.log(`baselining: merged PR #${pr.number} in-cycle — ${mergeReason(runs)}`);
729	      await deleteBranch(token, repo, pr.head?.ref);
730	      return true;
731	    }
732	    console.log(`baselining: could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
