748	  if (status !== 200) {
749	    console.log(`baselining: could not read the runs for PR #${pr.number}'s head (HTTP ${status})`);
750	    return pr;
751	  }
752	  const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
753	  const disposition = pullDisposition({ delivery, runs });
754	
755	  if (disposition === 'keep' || disposition === 'wait') {
756	    console.log(`baselining: keeping PR #${pr.number} (${disposition})`);
757	    return pr;
758	  }
759	
760	  if (disposition === 'merge') {
761	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
762	      method: 'PUT', body: { merge_method: 'squash' },
763	    });
764	    if (res.status === 200) {
765	      console.log(`baselining: merged PR #${pr.number} — ${mergeReason(runs)}`);
766	      await deleteBranch(token, repo, pr.head?.ref);
767	      return null;
768	    }
769	    console.log(`baselining: could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
770	      + ' — closing it instead; the converge is idempotent and this cycle re-cuts it');
771	  }
772	
773	  // Closed, not left to rot: whatever went wrong on that head, the next converge
774	  // reproduces the same content from the same inputs. Named in the log because a
775	  // member closing its maintenance PR every single night is a repo whose CI needs
776	  // a human, and the pattern has to be visible to be noticed.
777	  const closed = await gh(token, `/repos/${repo}/pulls/${pr.number}`, { method: 'PATCH', body: { state: 'closed' } });
778	  if (closed.status !== 200) {
779	    console.log(`baselining: could not close PR #${pr.number} (${closed.status}) — leaving it and skipping this cycle`);
780	    return pr;
781	  }
782	  console.log(`baselining: closed PR #${pr.number} — it did not land (${failureSummary(runs)}); re-cutting this cycle`);
783	  await deleteBranch(token, repo, pr.head?.ref);
784	  return null;
785	}
786	
787	// Tidy the ref behind a disposed PR — a closed branch left on the remote is litter
788	// that accumulates one per cycle. Never fatal: the branch is not the deliverable.
789	async function deleteBranch(token, repo, ref) {
790	  if (!ref) return;
791	  const res = await gh(token, `/repos/${repo}/git/refs/heads/${encodeURIComponent(ref)}`, { method: 'DELETE' });
792	  if (res.status !== 204) console.log(`baselining: could not delete branch ${ref} (HTTP ${res.status})`);
793	}
794	
795	// The I/O half of the CI dispatch (#565): read the workflow files as they exist
796	// ON THE MAINTENANCE BRANCH (the converge may itself have changed them), plan
797	// with ciDispatchPlan, POST a dispatch per selected workflow, and log every
798	// outcome — a silent no-checks PR is exactly the failure mode this exists to
799	// close. Needs the scheduler workflow's `actions: write` (a read-only token
800	// 403s the POST silently — the store-release lesson).
801	async function dispatchCiRuns(token, repo, branch) {
802	  const ref = encodeURIComponent(branch);
803	  const { json: dir } = await gh(token, `/repos/${repo}/contents/.github/workflows?ref=${ref}`);
804	  const files = [];
805	  for (const entry of Array.isArray(dir) ? dir : []) {
806	    if (!/\.ya?ml$/.test(entry.name ?? '')) continue;
807	    const { json } = await gh(token, `/repos/${repo}/contents/.github/workflows/${entry.name}?ref=${ref}`);
808	    files.push({ name: entry.name, content: json?.content ? Buffer.from(json.content, 'base64').toString('utf8') : '' });
809	  }
810	  const { dispatch, missing } = ciDispatchPlan(files);
811	  for (const name of missing) {
812	    console.log(`baselining: ${name} runs on pull_request but has no workflow_dispatch trigger — `
813	      + 'cannot start it on the maintenance PR; add `workflow_dispatch:` under its `on:` to let baselining run it');
814	  }
815	  if (!dispatch.length && !missing.length) {
816	    console.log('baselining: no pull_request-triggered workflow — the maintenance PR has no checks to wait for');
817	  }
818	  for (const name of dispatch) {
819	    const res = await gh(token, `/repos/${repo}/actions/workflows/${name}/dispatches`, {
820	      method: 'POST', body: { ref: branch },
821	    });
822	    if (res.status === 204) console.log(`baselining: dispatched ${name} on ${branch} — the maintenance PR gets its checks`);
823	    else console.log(`baselining: could not dispatch ${name} on ${branch} (${res.status})`);
824	  }
825	  return { dispatch, missing };
826	}
827	
828	// Ask the owner to add a repo Actions secret a task declares in `required_secrets`
829	// but the repo has not configured. The wiring converge stamps every declared name
830	// into the scheduler workflow, so by the time this runs the value is either in the
831	// environment or genuinely unset — no separate probe needed.
832	//
833	// This is the adoption interview's posture, not a gate: nothing fails, no check
834	// fires, and the task that needs the secret simply doesn't work until someone adds
835	// it. One open issue per repo (matched by exact title) so an unconfigured secret
836	// costs one issue, not one per night. Exported for the tests.
837	export const SECRETS_ISSUE_TITLE = 'Claudinite: configure required Actions secrets';
838	
839	export function unconfiguredSecrets(declared, env) {
840	  return (declared ?? []).filter((name) => !env[name]);
841	}
842	
843	async function askForSecrets(token, repo, names) {
844	  const q = encodeURIComponent(`repo:${repo} in:title "${SECRETS_ISSUE_TITLE}" state:open`);
845	  const { json } = await gh(token, `/search/issues?q=${q}&per_page=10`);
846	  if ((json?.items ?? []).some((i) => (i.title ?? '').trim() === SECRETS_ISSUE_TITLE)) return false;
847	  const body = [
848	    'A scheduled task in this repo declares a repo **Actions secret** that is not configured yet.',
849	    'Until it is, that task cannot do its work — everything else keeps running normally.',
850	    '',
851	    ...names.map((n) => `- \`${n}\``),
852	    '',
853	    `Add each one at https://github.com/${repo}/settings/secrets/actions, then close this issue.`,
854	  ].join('\n');
855	  await gh(token, `/repos/${repo}/issues`, { method: 'POST', body: { title: SECRETS_ISSUE_TITLE, body } });
856	  return true;
857	}
858	
859	// Arm native auto-merge on a PR (by node id) via the GraphQL mutation — the REST
860	// `PUT /merge` would merge NOW, ignoring pending checks; this waits for them.
861	async function enableAutoMerge(token, pullRequestId) {
862	  const query = 'mutation($id:ID!){enablePullRequestAutoMerge(input:{pullRequestId:$id,mergeMethod:SQUASH}){pullRequest{id}}}';
863	  const res = await fetch(`${API}/graphql`, {
864	    method: 'POST',
865	    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
866	    body: JSON.stringify({ query, variables: { id: pullRequestId } }),
867	  });
868	  const json = await res.json().catch(() => null);
869	  if (json?.errors?.length) throw new Error(json.errors[0].message);
870	}
871	
872	export async function main() {
873	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
874	  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
875	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
876	  const token = process.env.GITHUB_TOKEN;
877	  const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
878	  // Set by deliver() to `{ branch, pr, merged }`; stays null when this cycle opened
879	  // nothing, which is what the dispatch issue then says.
880	  let delivered = null;
881	  if (!repo) { console.error('baselining: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
882	  if (!token) { console.error('baselining: no GITHUB_TOKEN in env'); process.exit(1); }
883	
884	  const checksPath = join(root, '.claudinite-checks.json');
885	  if (!existsSync(checksPath)) { console.log('baselining: no .claudinite-checks.json — nothing to self-refresh'); return; }
886	  const priorRaw = JSON.parse(readFileSync(checksPath, 'utf8'));
887	  const priorStamp = priorRaw.claudinite ?? {};
888	  if (!priorStamp.updated && !priorStamp.ref) {
889	    console.log('baselining: no vendored-mount stamp — nothing to self-refresh (canon home or pre-adoption)');
890	    return; // quiet, no agent (matches the precondition self-skip)
891	  }
892	  const { delivery, materialize } = resolveDelivery(priorRaw?.maintenance?.delivery);
893	  if (!delivery) {
894	    console.error(`baselining: maintenance.delivery "${priorRaw?.maintenance?.delivery}" is neither auto-merge nor review`);
895	    process.exit(1);
896	  }
897	  // Materialize the missing key BEFORE the converge, so the repair rides this
898	  // cycle's maintenance commit like any other converged surface.
899	  if (materialize) {
900	    priorRaw.maintenance = { ...priorRaw.maintenance, delivery };
901	    writeFileSync(checksPath, JSON.stringify(priorRaw, null, 2) + '\n');
902	    console.log(`baselining: maintenance.delivery was missing — materialized "${delivery}"`);
903	  }
904	
905	  // 1. Fetch canon at head as a ROOTLESS tree (drop .git so apply-vendor-set's
906	  //    ancestry guards skip — a shallow clone can't answer them, and it is head
907	  //    by construction).
908	  const source = canonSource(process.env);
909	  const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
910	  git(source.ref
911	    ? ['clone', '--depth', '1', '--branch', source.ref, source.url, tmp]
912	    : ['clone', '--depth', '1', source.url, tmp]);
913	  const headSha = git(['-C', tmp, 'rev-parse', 'HEAD']).trim();
914	  rmSync(join(tmp, '.git'), { recursive: true, force: true });
915	  if (source.rehearsal) {
916	    console.log(`baselining: REHEARSAL against ${source.url}@${source.ref} (${headSha.slice(0, 8)}) — `
917	      + 'the stamp will be restored, and nothing is delivered');
918	  }
919	
920	  // 2-4. Deterministic converge: mount + stamp, then wiring, then mechanical notes.
921	  node([join(tmp, 'vendoring/apply-vendor-set.mjs'), '--target', root, '--ref', headSha]);
922	  const wiringOut = node([join(tmp, 'engine/scheduler/converge-wiring.mjs'), repo], { CLAUDINITE_REPO_ROOT: root });
923	  // The handshake (migrations/registry.mjs, WITHHOLD_CAPABLE_ENV): THIS worker withholds
924	  // workflow paths from its commit and hands them to the agent, so a record may safely
925	  // materialize one. An older vendored worker does not set it and the materialization is
926	  // skipped instead of wedging its push. Set here, by the code that does the withholding,
927	  // because the question is what the RUNNING process can do — and the disk cannot answer
928	  // it: apply-vendor-set above has already overwritten this very file with the new
929	  // version while this old-or-new code is the thing actually executing.
930	  node([join(tmp, 'migrations/apply.mjs')], { CLAUDE_PROJECT_DIR: root, CLAUDINITE_CAN_WITHHOLD_WORKFLOWS: '1' });
931	
932	  // Ask about any declared secret the repo hasn't configured — but only once the
933	  // wiring is settled. On the cycle that FIRST stamps a name into the workflow the
934	  // value cannot be in this process's env yet, so asking then would nag about a
935	  // secret the owner may well have already added; next cycle tells the truth.
936	  const { declaredSecrets } = await import(pathToFileURL(join(tmp, 'engine/scheduler/converge-wiring.mjs')).href);
937	  const missingSecrets = wiringOut.includes('.github/workflows/claudinite-scheduler.yml')
938	    ? []
939	    : unconfiguredSecrets(await declaredSecrets(root, JSON.parse(readFileSync(checksPath, 'utf8'))), process.env);
940	  if (missingSecrets.length && await askForSecrets(token, repo, missingSecrets)) {
941	    console.log(`baselining: asked the owner to configure ${missingSecrets.join(', ')}`);
942	  }
943	
944	  // 5. Pending agentic notes (from the fresh canon clone) + stamp hold.
945	  const { loadMigrations, agenticMigrations } = await import(pathToFileURL(join(tmp, 'migrations/registry.mjs')).href);
946	  const pending = pendingAgentic(agenticMigrations(await loadMigrations()), priorStamp.updated);
947	  if (pending.length) {
948	    const raw = JSON.parse(readFileSync(checksPath, 'utf8'));
949	    raw.claudinite = { ...raw.claudinite, updated: heldStamp(pending) };
950	    writeFileSync(checksPath, JSON.stringify(raw, null, 2) + '\n');
951	  }
952	
953	  // 6. Meaningful change? A stamp-only bump against an unchanged head is not one —
954	  //    revert it and stay quiet (no nightly stamp-only noise).
955	  const changed = git(['-C', root, 'status', '--porcelain'])
956	    .split('\n').map((l) => l.slice(3)).filter(Boolean);
957	  // `materialize` excluded: a materialized delivery key also touches only
958	  // .claudinite-checks.json, and reverting it would re-drift the repo every night
959	  // and never land the repair.
960	  const onlyStamp = changed.length > 0 && !materialize && changed.every((p) => p === '.claudinite-checks.json');
961	  if (onlyStamp && priorStamp.ref === headSha && !pending.length) {
962	    git(['-C', root, 'checkout', '--', '.claudinite-checks.json']);
963	    console.log('baselining: mount already at canon head, nothing changed — agentless, quiet');
964	    return;
965	  }
966	  const meaningfulChange = changed.length > 0;
967	  // What this stage cannot push. Computed here, before the escalation gate, because a
968	  // withheld file is residual work for the agent exactly like a pending agentic note.
969	  const withheld = withheldWorkflowPaths(changed);
970	  if (withheld.length) {
971	    console.log(`baselining: withholding ${withheld.length} workflow file(s) from the push — `
972	      + `the Action token cannot write .github/workflows/; the agent stage lands them: ${withheld.join(', ')}`);
973	  }
974	
975	  // 6b. SELF-TEST the converged tree before judging its content. This asks "can
976	  //     Claudinite still run here?" — mount, stamp, pack manifests, hook targets,
977	  //     mounted skills, cron, migrations registry — and it is the gate that would
978	  //     have caught #555 the night it landed: a required manifest field arrived
979	  //     with no migration, every consumer pack stopped validating, and because a
980	  //     pack that fails validation contributes NO rules, check_the_world went on
981	  //     reporting green about a corpus it was no longer running. A content check
982	  //     cannot see its own machinery break. This runs on the just-converged tree,
983	  //     so it judges what the member is about to live with.
984	  const selftest = runSelfTest(root);
985	  if (!selftest.ok) {
986	    console.log('baselining: the converged mount FAILED its self-test — requesting the agent');
987	    logGateOutput('selftest --strict', selftest);
988	  }
989	
990	  // 7. Escalation gate: run the conformance checks only when a change happened and
991	  //    no agentic note already forces the agent. A failed self-test forces it too:
992	  //    broken machinery is exactly the judgment case, and merging it would spread
993	  //    the breakage to a repo that was working an hour ago.
994	  const checks = (meaningfulChange && !pending.length) ? runCheckTheWorld(root) : GATE_ABSENT;
995	  if (!checks.ok) logGateOutput('check_the_world', checks);
996	  const reason = escalation({
997	    pendingCount: pending.length, meaningfulChange, checksPass: checks.ok, selftestOk: selftest.ok,
998	    withheldCount: withheld.length, checksCrashed: checks.crashed, selftestCrashed: selftest.crashed,
999	  });
1000	  const requestAgent = reason !== null;
1001	
1002	  // 7b. A REHEARSAL stops here. It has done the only thing it was for — converged
1003	  //     this real repo against a canon BRANCH and asked whether the result still
1004	  //     works — and now it must leave no trace: no commit, no branch, no PR, and
1005	  //     above all no stamp. Stamping a branch head would leave the member
1006	  //     `ref-not-on-trunk`, which the #328 anti-rewind guard then refuses to
1007	  //     converge over: a rehearsal that wedged the repo it was rehearsing on.
1008	  //     `git checkout -- .` restores the working tree wholesale, so the mount goes
1009	  //     back to the vendored snapshot the repo actually runs.
1010	  if (source.rehearsal) {
1011	    git(['-C', root, 'checkout', '--', '.']);
1012	    const verdict = selftest.ok && checks.ok ? 'PASS' : 'FAIL';
1013	    console.log(`baselining: rehearsal ${verdict} — selftest ${selftest.ok ? 'ok' : 'FAILED'}, `
1014	      + `checks ${checks.ok ? 'green' : 'RED'}, ${changed.length} file(s) would have changed. Working tree restored.`);
1015	    if (verdict === 'FAIL') process.exit(1);   // the canary's whole purpose: fail the canon PR
1016	    return;
1017	  }
1018	
1019	  // 8. Deliver the converge (only when there's something to land).
1020	  if (meaningfulChange || pending.length) {
1021	    const seed = Math.random().toString(36).slice(2, 8);
1022	    delivered = await deliver(root, repo, base, token, delivery, seed, withheld);
1023	    console.log(`baselining: delivered converge on ${delivered.branch}${delivered.pr ? ` (PR #${delivered.pr}${delivered.merged ? ', merged' : ''})` : ''} (${delivery})`);
1024	  } else {
1025	    console.log('baselining: no change to deliver');
1026	  }
1027	
1028	  // 9. Request the agent only when judgment is left (conditional handoff, §3) — naming
1029	  //    what this run created AND why the agent is being woken. `delivered` stays null
1030	  //    when nothing was opened, and the issue then names nothing; `reason` is non-null
1031	  //    exactly when the agent is requested at all.
1032	  if (requestAgent && requestFile) {
1033	    writeFileSync(requestFile, `${JSON.stringify({ marker: AGENT_REQUEST_MARKER, delivered, reason })}\n`);
1034	  }
1035	  console.log(requestAgent
1036	    ? `baselining: requested agent stage (${reason.code}: ${reason.detail})`
1037	    : 'baselining: agentless night — deterministic converge delivered, no agent needed');
1038	}
1039	
1040	// Run only when invoked directly (the scheduler's `node worker.mjs`), never on
1041	// import — a test imports the pure helpers without any git or network.
1042	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
1043	  main().catch((e) => { console.error(`baselining preprocessing failed: ${e.message}`); process.exit(1); });
1044	}
1045

