1	// Print one machine-readable execution record for the dispatch this executor
2	// session ran — `claudinite-task-exec v1 <pack>/<task> [<slot>] <status>`
3	// (run-record.mjs, the single home of the format). The executor runs this in
4	// code at step 4, right after converging its issue, so the record lands in the
5	// session transcript exactly as printed; the capture step ships the transcript
6	// to the conversation-logs branch, and the usage fold counts the statuses out
7	// of it deterministically. Hard-coded on purpose: the count must never depend
8	// on how an agent chose to phrase its final message.
9	//
10	// The code-decided terminal verdicts (`task-gone`, `invalid`) are printed by
11	// resolve-dispatch.mjs itself; this CLI exists for the two verdicts only the
12	// end of the run can know (`success`, `failed`).
13	//
14	// Usage: node record-exec.mjs <pack>/<task> <slot> <success|failed>
15	
16	import { pathToFileURL } from 'node:url';
17	import { renderTaskExec, TASK_EXEC_STATUSES } from './run-record.mjs';
18	
19	export function execRecordLine(argv) {
20	  const [family, slotId, status] = argv;
21	  const m = /^([^/\s]+)\/([^/\s]+)$/.exec(family ?? '');
22	  if (!m) return { error: `first argument must be <pack>/<task>, got ${JSON.stringify(family ?? null)}` };
23	  if (!slotId) return { error: 'second argument must be the slot id (from the dispatch brief)' };
24	  if (!TASK_EXEC_STATUSES.includes(status)) {
25	    return { error: `third argument must be one of ${TASK_EXEC_STATUSES.join(', ')}, got ${JSON.stringify(status ?? null)}` };
26	  }
27	  return { line: renderTaskExec({ pack: m[1], task: m[2], slotId, status }) };
28	}
29	
30	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
31	  const { line, error } = execRecordLine(process.argv.slice(2));
32	  if (error) {
33	    console.error(`record-exec: ${error} — usage: node record-exec.mjs <pack>/<task> <slot> <${TASK_EXEC_STATUSES.join('|')}>`);
34	    process.exit(2);
35	  }
36	  console.log(line);
37	}
